CREATE TABLE "Client" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "phone" varchar(20) UNIQUE NOT NULL,
  "email" varchar(255),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "Trainer" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "phone" varchar(20),
  "specialization" varchar(100),
  "is_active" boolean DEFAULT true
);

CREATE TABLE "Section" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "description" text,
  "level" varchar(20)
);

CREATE TABLE "Hall" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) NOT NULL,
  "capacity" int NOT NULL,
  "address" varchar(255)
);

CREATE TABLE "Lesson" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "trainer_id" int NOT NULL,
  "hall_id" int NOT NULL,
  "section_id" int NOT NULL,
  "start_at" timestamp NOT NULL,
  "duration_min" int NOT NULL,
  "capacity" int NOT NULL,
  "status" varchar(20) DEFAULT 'planned'
);

CREATE TABLE "Booking" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "client_id" int NOT NULL,
  "lesson_id" int NOT NULL,
  "status" varchar(20) DEFAULT 'confirmed',
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "Attendance" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "visited" boolean DEFAULT false,
  "marked_at" timestamp
);

ALTER TABLE "Lesson" ADD FOREIGN KEY ("trainer_id") REFERENCES "Trainer" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Lesson" ADD FOREIGN KEY ("hall_id") REFERENCES "Hall" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Lesson" ADD FOREIGN KEY ("section_id") REFERENCES "Section" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Booking" ADD FOREIGN KEY ("client_id") REFERENCES "Client" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Booking" ADD FOREIGN KEY ("lesson_id") REFERENCES "Lesson" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Attendance" ADD FOREIGN KEY ("booking_id") REFERENCES "Booking" ("id") DEFERRABLE INITIALLY IMMEDIATE;
